const parts = $('Get full email').first().json.payload.parts || [];
const textPart = parts.find(p => p.mimeType === 'text/plain');
const raw = textPart.body.data.replace(/-/g, '+').replace(/_/g, '/');
const rawBody = decodeURIComponent(escape(atob(raw)));


// Strip everything after the footer separator
const content = rawBody.split('You received this email')[0];

// Clean up whitespace and carriage returns
const clean = content
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/----------/g, '')
  .trim();

// Extract the job URL
const urlMatch = clean.match(/https:\/\/www\.upwork\.com\/jobs\/~\d+/);
const jobUrl = urlMatch ? urlMatch[0] : null;

// Strip tracking URLs and tag links, keep just the text
const stripped = clean
  .replace(/https?:\/\/\S+/g, '')  // remove all URLs
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return {
  json: {
    posting: stripped,
    jobUrl: jobUrl
  }
};

const posting = $('Email cleanup').first().json.posting;
const jobUrl = $('Email cleanup').first().json.jobUrl;
const profile = $('Get a document').first().json.content;

const systemPrompt = `You are a job posting triage agent for a freelance developer. Your task is to score Upwork job postings against the developer's profile and preferences.

<developer_profile>
${profile}
</developer_profile>

Score the posting from 1-5:
5 = Strong match, apply immediately
4 = Worth a look, aligns with goals
3 = Borderline, surface but flag concerns
2 = Weak fit, only if nothing better
1 = Skip entirely

Respond ONLY with valid JSON, no markdown, no preamble:
{
  "score": 3,
  "category": "strong_match | worth_a_look | skip",
  "rationale": "One sentence explaining why",
  "concerns": "One sentence on yellow/red flags, or null"
}

Rules:
- Use the Rate Thresholds, Skip list, and Client Credibility Signals from the profile strictly
- If the posting matches any Skip criteria, score 1 and category "skip"
- If client credibility has red flags, score 1 and category "skip"
- Be harsh — surfacing noise wastes the developer's time
- Do NOT wrap the response in markdown code fences or backticks`;

const userMessage = `<upwork_posting>
${posting}
</upwork_posting>`;

return {
  json: {
    requestBody: {
      model: "claude-haiku-4-5-20251001",
      max_tokens: 256,
      system: systemPrompt,
      messages: [
        {
          role: "user",
          content: userMessage
        }
      ]
    },
    jobUrl: jobUrl
  }
};

const response = $input.first().json;

const raw = response.content[0].text;
const clean = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const result = JSON.parse(clean);

const jobUrl = $('prompt builder').first().json.jobUrl;
const posting = $('Email cleanup').first().json.posting;

// Filter out low scores
if (result.score < 3) {
  return [];  // empty array = n8n stops this branch
}

// Star rating visual
const stars = '⭐'.repeat(result.score);

// Build Telegram message
const message = `${stars} Score: ${result.score}/5

${result.rationale}

${result.concerns ? `⚠️ ${result.concerns}` : ''}

---
${posting.split('\n').slice(0, 10).join('\n')}

🔗 ${jobUrl || 'No link found'}`;

return {
  json: {
    message: message,
    score: result.score,
    category: result.category,
    inputTokens: response.usage.input_tokens,
    outputTokens: response.usage.output_tokens
  }
};
